"""Prepare one matched rootfs component comparison after a real DAX Guest pass.

One new private tools copy and one reviewed cap0 KVM job. No SDK, deployment,
original image change or cache dropping. All N=1/2 block/pmem results are retained.
"""
import argparse,base64,hashlib,json,os,re,socket,stat,subprocess,sys
from pathlib import Path

PAYLOAD={'entry.py': {'base64': 'aW1wb3J0IHN5cwpmcm9tIHBhdGhsaWIgaW1wb3J0IFBhdGgKc3lzLnBhdGguaW5zZXJ0KDAsc3RyKFBhdGgoX19maWxlX18pLnJlc29sdmUoKS5wYXJlbnQpKQppbXBvcnQgaG9zdF9jb21wYXJlCnJhaXNlIFN5c3RlbUV4aXQoaG9zdF9jb21wYXJlLm1haW4oKSkK', 'sha256': '3071f6b7d17a58a183d33275098f4d699bd3d1e1163ac04bd3d827d903cb0389', 'bytes': 150}, 'host_compare.py': {'base64': '', 'sha256': '1f61af9cbdc97ab54c52f3f1d3a24f7781ed656d4e09bb99423dc8a940444211'}, 'native_pmem_guest.py': {'base64': '', 'sha256': '5076f7b5bc36e67debf75f0a8d35453bdb15c1852f58a6e2f5f1b22a55ebf9bc', 'bytes': 17977}, 'metrics.py': {'base64': '', 'sha256': '1cec20290c4aae7b6354112fc4bc07ca8bbc8623f0f5b0ff5f304a08aa62cdfb', 'bytes': 6422}, 'cgroup_memory.py': {'base64': '', 'sha256': '0d72ec96c821690e80defe1582c80a4a808e9ab6094e5c0d33187c85daa3199f', 'bytes': 13283}, 'cache-init.sh': {'base64': '', 'sha256': 'b372e1053793a8edd8feb270bb6e8dcf517218c31716d1f0a0350c1e443bfe7e', 'bytes': 5063}, 'cache-statx-arm64': {'base64': '', 'sha256': 'b93bcab05f83706763cb1f9cee4514351178f763605f5d2f3ff689830dcdc11a', 'bytes': 2556064}, 'cache-statx.go': {'base64': '', 'sha256': '68b82016756c59459b3ff4a1a88a9e7a64d5662f92419b80015f4c6d90958d5c'}}
ROOT=Path('/home/jwk/agent')


def need(ok,message):
    if not ok:raise RuntimeError(message)


def read(path,limit=1024**2):
    p=Path(path);need(p.is_absolute() and p.resolve(strict=True)==p and p.is_relative_to(ROOT),'Missing/redirected input')
    with p.open('rb') as f:
        before=os.fstat(f.fileno());need(stat.S_ISREG(before.st_mode) and before.st_uid==1204 and before.st_size<=limit,'Input owner/type/size differs')
        raw=f.read(limit+1);after=os.fstat(f.fileno())
    need(len(raw)==before.st_size and (before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns),'Input changed')
    return raw


def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        before=os.fstat(f.fileno());need(stat.S_ISREG(before.st_mode),'Regular input required')
        for block in iter(lambda:f.read(1024**2),b''):h.update(block)
        after=os.fstat(f.fileno())
    need((before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns),'Input changed while hashing')
    return h.hexdigest()


def put(path,raw):
    with path.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())


def root_block(node,stage,files,environment):
    values={'HOST':'server1' if node=='node-a' else 'agent1','UNIT':'jwk-rootfs-cache-compare-'+node+'-v1.service',
        'STAGE':str(stage),'FILES':files,'EXTRA_ENV':environment}
    code='''import hashlib,os,socket,stat,subprocess
from pathlib import Path
assert os.geteuid()==0 and socket.gethostname()==HOST,'Use intended node root terminal'
assert subprocess.check_output(['/usr/bin/id','-u','jwk'],text=True).strip()=='1204'
assert subprocess.check_output(['/usr/bin/id','-g','jwk'],text=True).strip()=='1205'
assert subprocess.check_output(['/usr/bin/getent','group','kvm'],text=True).split(':')[2]=='36'
assert subprocess.check_output(['/usr/bin/systemctl','show',UNIT,'--property=LoadState','--value'],text=True).strip()=='not-found','Existing comparison unit preserved'
for name,pin in FILES.items():
 p=Path(name);assert p.resolve(strict=True)==p and p.is_relative_to(Path('/home/jwk/agent'))
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK);before=os.fstat(fd)
 assert stat.S_ISREG(before.st_mode) and before.st_uid==1204 and before.st_size<=131072
 with os.fdopen(fd,'rb') as f:raw=f.read(131073);after=os.fstat(f.fileno())
 assert len(raw)==before.st_size and (before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns)
 assert hashlib.sha256(raw).hexdigest()==pin,'Reviewed comparison code/config changed'
output=Path(STAGE)/'results';assert not output.exists() and not output.is_symlink()
assert Path('/dev/kvm').is_char_device()
command=['/usr/bin/systemd-run','--unit='+UNIT,'--collect','--wait','--pipe',
 '--property=Description=Matched synthetic rootfs cache block versus pmem comparison',
 '--property=User=jwk','--property=Group=jwk','--property=SupplementaryGroups=kvm',
 '--property=CapabilityBoundingSet=','--property=AmbientCapabilities=',
 '--property=NoNewPrivileges=yes','--property=PrivateNetwork=yes','--property=PrivateTmp=yes',
 '--property=Type=exec','--property=Restart=no','--property=KillMode=control-group',
 '--property=RuntimeMaxSec=600s','--property=TimeoutStopSec=20s','--property=LimitNOFILE=4096',
 '--property=MemoryMax=1536M','--property=UMask=0077']
for key,value in EXTRA_ENV.items():
 assert key=='GLIBC_TUNABLES' and value=='glibc.pthread.rseq=0'
 command.append('--property=Environment='+key+'='+value)
command+=['/usr/bin/python3','-I','-B',str(Path(STAGE)/'payload/entry.py'),'--config',str(Path(STAGE)/'compare.json'),'--output',str(output),'--run']
result=subprocess.run(command)
print('ROOTFS_COMPONENT_UNIT_EXIT='+str(result.returncode),flush=True)
raise SystemExit(result.returncode)
'''
    return "/usr/bin/python3 -I -B - <<'ROOTFS_CACHE_COMPONENT_REVIEWED_ROOT'\n"+''.join(k+'='+repr(v)+'\n' for k,v in values.items())+code+"ROOTFS_CACHE_COMPONENT_REVIEWED_ROOT\n"


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--node',choices=('node-a','node-b'),default='node-a')
    parser.add_argument('--dax-pass-report',required=True)
    parser.add_argument('--guest-config',help='Exact standalone configuration used by the passing DAX run')
    parser.add_argument('--run',action='store_true');args=parser.parse_args()
    base=ROOT/('r/pm-a-v1' if args.node=='node-a' else 'r/pm-b-v1');stage=base/'cache-compare-v1'
    report={'revision':'rootfs-cache-component-prepare-v1','status':'PLAN_ONLY_AFTER_REAL_DAX_PASS',
        'node':args.node,'stage':str(stage),'matrix':['block1','pmem1','block2','pmem2'],
        'commonFileBytes':8388608,'holdSeconds':30,'maxSimultaneousGuests':2,
        'Guest_created':False,'SDK_called':False,'services_changed':False,'originalImagesModified':False,
        'memfileCoWAccepted':False,'globalNetPhysicalSavingBytes':None}
    if not args.run:print(json.dumps(report,indent=2));return 0
    try:
        need(sys.platform=='linux' and os.uname().machine=='aarch64' and socket.gethostname()==('server1' if args.node=='node-a' else 'agent1'),'Use intended ARM64 node')
        need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary jwk, no sudo')
        caps=dict(line.split(':',1) for line in Path('/proc/self/status').read_text().splitlines() if ':' in line)
        need(all(int(caps[k].strip(),16)==0 for k in ('CapInh','CapPrm','CapEff','CapAmb')),'Capability-free preparation required')
        need(base.resolve(strict=True)==base and not stage.exists() and stage.resolve()==stage,'New private comparison stage required')
        gate_path=Path(args.dax_pass_report);gate_raw=read(gate_path);gate=json.loads(gate_raw)
        need(gate.get('firecrackerExit')==0 and gate.get('timedOut') is False, 'Successful normal exit required')
        if gate.get('pinnedInputs',{}).get('traceRunner'):
            need(gate.get('allOwnedTraceesReaped') is True and gate.get('sigsysDiagnostics')==[], 'Unresolved trace or SIGSYS refused')
        need(gate.get('guestDaxSelftestPassed') is True and gate.get('firecrackerReaped') is True
             and gate.get('safeToRetireThisLease') is True,'Actual successful DAX Guest report required before image preparation')
        config_path=Path(args.guest_config) if args.guest_config else base/'native-session/guest-config.json'
        guest=json.loads(read(config_path,32768));need(gate.get('providerSpec')==guest['providerSpec'],'DAX pass tested another provider generation')
        for key in ('firecracker','kernel'):need(gate['pinnedInputs'][key]['sha256']==guest[key]['sha256'],'DAX pass used other FC/kernel')
        selected=guest.get('seccompFilter');proven=gate.get('pinnedInputs',{}).get('seccompFilter')
        if selected is not None or proven is not None:
            need(isinstance(selected,dict) and set(selected)=={'path','sha256','bytes'} and isinstance(proven,dict)
                 and type(selected['bytes']) is int and 0<selected['bytes']<=1024**2
                 and re.fullmatch(r'[0-9a-f]{64}',selected['sha256']) is not None
                 and selected['sha256']==proven.get('sha256') and selected['bytes']==proven.get('bytes'),
                 'Actual passing custom seccomp filter is missing or differs')
            if 'path' in proven:need(selected['path']==proven['path'],'Custom seccomp path differs from actual pass')
            filter_path=Path(selected['path']);need(filter_path.resolve(strict=True)==filter_path
                and filter_path.stat().st_size==selected['bytes'] and sha(filter_path)==selected['sha256'],
                'Passing custom seccomp filter changed')
        trace=guest.get('traceRunner');trace_pin=gate.get('pinnedInputs',{}).get('traceRunner')
        if trace is not None or trace_pin is not None:
            need(isinstance(trace,dict) and {'path','sha256'}<=set(trace)<={'path','sha256','bytes'}
                 and isinstance(trace_pin,dict) and trace['sha256']==trace_pin.get('sha256')
                 and ('bytes' not in trace or trace['bytes']==trace_pin.get('bytes')),
                 'Actual passing diagnostic tracer pin is missing or differs')
        environment=gate.get('firecrackerEnvironment',{})
        need(isinstance(environment,dict) and set(environment)<={'GLIBC_TUNABLES'},'Unreviewed passing FC environment')
        if environment:need(environment['GLIBC_TUNABLES']=='glibc.pthread.rseq=0','Unreviewed explicit passing FC environment')
        artifact=json.loads(read(base/'return.json'));need(artifact.get('originalToolsUnchanged') is True,'Artifact receipt is not complete')
        lower=artifact['artifacts']['lower'];need('sha256:'+lower['sha256']==guest['providerSpec']['sha256'],'Baseline ext4 differs from native base')
        image=Path(guest['tools']['path']);need(sha(image)==guest['tools']['sha256'],'Original standalone tools pin differs')
        expected=artifact['guestInputs'].get('commonFileSha256')
        if expected is None:
            source=base/'probe/return.json'
            expected=json.loads(read(source))['sourceFiles']['common-data.bin']
        need(re.fullmatch(r'[0-9a-f]{64}',expected) is not None,'Expected common-data SHA256 required')
        debug=ROOT/'deployments/agentenv-ub-b019f27/native/bin/debugfs'
        need(debug.resolve(strict=True)==debug and debug.is_file() and os.access(debug,os.X_OK),'Existing private debugfs required')
        need(sha(debug)=='bc53991ef4ee2d20a8c27b7aeed2e2c59cb40d5291292d1742ee01bd4ca50707','Reviewed debugfs changed')
        native=ROOT/'deployments/agentenv-ub-b019f27/native'
        debug_env=dict(os.environ)
        for key in ('LD_PRELOAD','LD_AUDIT'):debug_env.pop(key,None)
        debug_env['LD_LIBRARY_PATH']=str(native/'lib')+os.pathsep+str(native/'fallback/lib')
        import shutil
        need(shutil.disk_usage(base).free>=2*1024**3,'2GiB free disk required')
        stage.mkdir(mode=0o700);payload=stage/'payload';payload.mkdir(mode=0o700)
        for name,item in PAYLOAD.items():
            need(Path(name).name==name,'Invalid embedded payload name')
            raw=base64.b64decode(item['base64'],validate=True)
            need(hashlib.sha256(raw).hexdigest()==item['sha256'],'Embedded payload differs')
            put(payload/name,raw)
        target=stage/'tools-cache.ext4';shutil.copyfile(image,target)
        need(sha(target)==guest['tools']['sha256'],'Private tools copy differs before patch')
        def debug_run(command,index):
            with (stage/('debugfs-'+str(index)+'.log')).open('xb') as log:
                rc=subprocess.run([str(debug),'-w','-R',command,str(target)],env=debug_env,stdout=log,stderr=subprocess.STDOUT,timeout=30).returncode
            need(rc==0,'Private tools debugfs failed; inspect its new log')
        index=0
        for name,destination,mode in [('cache-init.sh','/agentenv/cache-init.sh','0100755'),('cache-statx-arm64','/agentenv/cache-statx','0100755')]:
            debug_run('write '+str(payload/name)+' '+destination,index);index+=1
            for field,value in [('mode',mode),('uid','0'),('gid','0')]:debug_run('set_inode_field '+destination+' '+field+' '+value,index);index+=1
            dumped=stage/('verified-'+name)
            debug_run('dump '+destination+' '+str(dumped),index);index+=1
            need(sha(dumped)==PAYLOAD[name]['sha256'],'Private tools embedded verification differs')
        need(sha(image)==guest['tools']['sha256'],'Original tools changed externally; stop')
        guest['tools']={'path':str(target),'sha256':sha(target),'bytes':target.stat().st_size};guest['memoryMiB']=256
        config={'version':1,'guest':guest,'lower':lower,'expectedCommonSha256':expected,
            'daxPass':{'path':str(gate_path),'sha256':hashlib.sha256(gate_raw).hexdigest()},
            'firecrackerEnvironment':environment,'comparisonUnit':'jwk-rootfs-cache-compare-'+args.node+'-v1.service'}
        put(stage/'compare.json',(json.dumps(config,indent=2)+'\n').encode())
        files={str(payload/name):item['sha256'] for name,item in PAYLOAD.items() if name.endswith('.py')}
        files[str(stage/'compare.json')]=sha(stage/'compare.json')
        text=root_block(args.node,stage,files,config['firecrackerEnvironment']);put(stage/'root-review.txt',text.encode())
        report.update(status='ROOTFS_COMPONENT_INPUTS_PREPARED_NOT_GUEST_RUN',config=str(stage/'compare.json'),
            expectedCommonSha256=expected,newToolsSha256=guest['tools']['sha256'],rootReview=str(stage/'root-review.txt'),
            results=str(stage/'results/return.json'),originalToolsUnchanged=True)
        put(stage/'return.json',(json.dumps(report,indent=2)+'\n').encode())
        print('BEGIN_ROOTFS_COMPONENT_PREPARE');print(json.dumps(report,indent=2));print('END_ROOTFS_COMPONENT_PREPARE')
        print('BEGIN_ROOTFS_COMPONENT_REVIEWED_ROOT');print(text);print('END_ROOTFS_COMPONENT_REVIEWED_ROOT');return 0
    except Exception as error:
        report.update(status='STOPPED_ROOTFS_COMPONENT_PREPARATION',errorType=type(error).__name__,reason=str(error)[:1000])
        print(json.dumps(report,indent=2));return 1


if __name__=='__main__':raise SystemExit(main())
